                # Only id1 is numeric: numeric sorts before non-numeric
                return -1
            elif is_digit2:
                # Only id2 is numeric: non-numeric sorts after numeric
                return 1
            else:
                # Both non-numeric: compare by ASCII order
                if id1 < id2:
                    return -1
                if id1 > id2:
                    return 1

        # All shared identifiers are equal: fewer identifiers sorts first
        if len(pre1) < len(pre2):
            return -1
        if len(pre1) > len(pre2):
            return 1
        return 0

