        parsed = parse_version(v)
        major, minor, patch, prerelease = parsed
        # Return a tuple for sorting
        # Use (major, minor, patch) for numeric comparison
        # For pre-release, we need to return something that sorts correctly
        # We'll use a custom comparable object
        return (major, minor, patch, PreReleaseKey(prerelease))

